            'applications_json' => '["Replacement refiner segment plates for Double Disc Refiners and Conical Refiners", "Wedge-wire screen baskets and rotors for coarse, fine, and headbox pressure screens", "Pulper rotor and extraction plate replacement for High-Consistency and Low-Consistency pulpers", "Deflaker rings, agitator impellers, and wear scrapers across stock preparation systems"]',
            'materials_json' => '["17-4 PH Stainless Steel / SS-316L / High-Chrome Alloys (38–58 HRC)", "SS-316L / SS-316Ti Wedge-Wire with Hard Chrome Plating (100–200 microns)", "Cast SS-304 / SS-316 Rotors with Stellite / Tungsten Carbide hard-facing"]',
            'technical_specs_json' => '["Refiner Segment Sizes: 13\" to 54\" diameter", "Screen Basket Slot Widths: 0.08 mm – 0.50 mm", "Screen Basket Hole Sizes: 1.0 mm – 4.0 mm", "Screen Basket Open Area: 8% – 18%", "Hardness Rating: 35 HRC – 60 HRC", "Dynamic Balance Quality: ISO 1940 Grade G2.5"]',
            'needs_manual_review' => false,
            'notes' => 'Paper & Pulp Machinery product content updated.',
        ],    ];

        foreach ($rows as $row) {
            $table = $row['table'];
            unset($row['table']);

            $summaryColumn = $table === 'public_pages' ? 'excerpt' : 'summary';
            $contentColumn = $table === 'public_product_categories' ? 'description_html' : 'content_html';

            $payload = [
                $summaryColumn => $row['summary'] ?? null,
                $contentColumn => $row['content_html'] ?? null,
                'updated_at' => $now,
            ];

            if ($table === 'public_products') {
                $payload['key_features'] = $row['key_features_json'] ? json_decode($row['key_features_json'], true) : null;
                $payload['applications'] = $row['applications_json'] ? json_decode($row['applications_json'], true) : null;
                $payload['materials'] = $row['materials_json'] ? json_decode($row['materials_json'], true) : null;
                $payload['technical_specs'] = $row['technical_specs_json'] ? json_decode($row['technical_specs_json'], true) : null;
            }

            DB::table($table)->where('url_path', $row['url_path'])->update($payload);
        }
    }
}
